const D = { soil: .5, scale: 1, energy: .6, density: .5, hue: 40, speed: 1, x: .68, y: .3, alpha: .6, style: 'grime', act: 'drift', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const soil=cl(P.soil,0,1.2), sc=cl(P.scale,.5,2.2), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

if(al>0.002 && soil>0.002){
S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let wipe=0, fogK=1, glareRate=1;
if(act==='wipe'){ wipe=md(sec*.19+T*.010,1); glareRate=.7; }
else if(act==='fog'){ fogK=1+1.5*(.5+.5*Math.sin(sec*.8+T*.021)); glareRate=.55; }

// ---- Grime is invisible until something bright rakes it. The glare source wanders on a
// monotonic orbit, so different marks light up as it passes — that is both the physics
// and the motion floor, and it cannot re-phase away.
const gAng=.125*TD*glareRate, gAng2=.287*TD*glareRate+2.4;
const gx=W*(cl(P.x,0,1)+.30*Math.cos(gAng)+.11*Math.cos(gAng2));
const gy=Hh*(cl(P.y,0,1)+.26*Math.sin(gAng)+.10*Math.sin(gAng2));
const gR=u*(.30+.20*dens);
const glare=((.30+1.05*en)*(.55+.7*K.intensity)+S.tre*.28*en)*5.0;

// ---- style ----
const survey=(sty==='survey'), bloomy=(sty==='bloom');
const nSm=survey?0:Math.round((2+6*dens)*(sty==='fingerprint'?.4:1)*(sty==='scratched'?.5:1));
const nWh=(sty==='fingerprint')?Math.round(1+dens*2):(survey?0:(soil>.6?1:0));
const nSc=Math.round((3+18*dens)*(sty==='scratched'?2.2:1)*(bloomy?.25:1)*(survey?2.0:1));
const nFl=Math.round((14+50*dens)*(bloomy?.4:1));
const tintS=survey?8:(bloomy?26:16);

const dc=drawingContext, oldOp=dc.globalCompositeOperation;
noStroke(); noFill();

// how strongly is the glare hitting a mark at (x,y)?
const lit=(x,y,k)=>{ const dx=x-gx, dy=y-gy; return Math.exp(-(dx*dx+dy*dy)/(gR*gR*(k||1))); };

dc.globalCompositeOperation='lighter';

// ---- veiling glare: the whole front element hazes over around the source ----
if(!survey){
  const hr=gR*(1.15+.5*fogK*(bloomy?1.5:1));
  const rg=dc.createRadialGradient(gx,gy,0,gx,gy,hr);
  const ha=cl(.20*soil*glare*al*fogK*(bloomy?2.0:1),0,.34);
  rg.addColorStop(0,'rgba(226,232,246,'+ha.toFixed(4)+')');
  rg.addColorStop(.45,'rgba(214,222,240,'+(ha*.42).toFixed(4)+')');
  rg.addColorStop(1,'rgba(200,212,236,0)');
  dc.fillStyle=rg; dc.fillRect(gx-hr,gy-hr,hr*2,hr*2);
}

// ---- smears: sleeve-wipe arcs across the front element. Soft, so shadowBlur — on a
// handful of shapes only, and reset straight after.
for(let m=0;m<nSm;m++){
  const cx=fr(m*4.1+10)*W, cy=fr(m*4.1+11)*Hh;
  const rad=u*(.16+.34*fr(m*4.1+12))*sc;
  const a0=fr(m*4.1+13)*TAU, span=(.5+1.5*fr(m*4.1+14));
  const wdt=u*(.012+.040*fr(m*4.1+15))*sc;
  // a wipe redistributes the smears: they sweep round and thin out
  const wOff=wipe>0?(wipe*TAU*1.2):0;
  const wFade=wipe>0?cl(1-Math.abs(md(fr(m*4.1+16)-wipe,1)-.5)*3.0,.15,1):1;
  const li=lit(cx+Math.cos(a0+span*.5+wOff)*rad, cy+Math.sin(a0+span*.5+wOff)*rad, 1.6);
  const aa=cl((.075+.20*fr(m*4.1+17))*soil*glare*al*(.16+1.6*li)*wFade,0,.46);
  if(aa<.002) continue;
  const seg=14, pts=[];
  for(let k=0;k<=seg;k++){ const a2=a0+wOff+span*(k/seg);
    const wob=1+.12*Math.sin(k*1.7+m*2.3);
    pts.push([cx+Math.cos(a2)*(rad+wdt*.5)*wob, cy+Math.sin(a2)*(rad+wdt*.5)*wob]); }
  for(let k=seg;k>=0;k--){ const a2=a0+wOff+span*(k/seg);
    const wob=1-.10*Math.sin(k*1.3+m*1.1);
    pts.push([cx+Math.cos(a2)*(rad-wdt*.5)*wob, cy+Math.sin(a2)*(rad-wdt*.5)*wob]); }
  const cr=224+22*fr(m*4.1+18), cg=228+18*fr(m*4.1+19), cb=238;
  dc.shadowBlur=wdt*(survey?0:1.4); dc.shadowColor='rgba('+(cr|0)+','+(cg|0)+','+(cb|0)+','+(aa*.9).toFixed(4)+')';
  dc.fillStyle='rgba('+(cr|0)+','+(cg|0)+','+(cb|0)+','+aa.toFixed(4)+')';
  dc.beginPath(); dc.moveTo(pts[0][0],pts[0][1]);
  for(let k=1;k<pts.length;k++) dc.lineTo(pts[k][0],pts[k][1]);
  dc.closePath(); dc.fill();
}
dc.shadowBlur=0;

// ---- fingerprint whorls: someone put a thumb on the front element ----
for(let m=0;m<nWh;m++){
  const cx=fr(m*6.3+40)*W, cy=fr(m*6.3+41)*Hh;
  const rr=u*(.07+.06*fr(m*6.3+42))*sc;
  const li=lit(cx,cy,1.3);
  const aa=cl(.44*soil*glare*al*(.10+1.8*li),0,.56);
  if(aa<.002) continue;
  const sq=.62+.5*fr(m*6.3+43), rot=fr(m*6.3+44)*TAU;
  for(let r2=0;r2<15;r2++){
    const t2=(r2+1)/15;
    dc.strokeStyle='rgba(232,236,248,'+(aa*(1-t2*.45)).toFixed(4)+')';
    dc.lineWidth=Math.max(.7,u*.0016*sc);
    dc.beginPath();
    for(let k=0;k<=26;k++){
      const a2=k/26*TAU;
      // a whorl: loops that close over on themselves, not clean circles
      const rd=rr*t2*(1+.22*Math.sin(a2*2+r2*.55+rot)+.10*Math.sin(a2*3-r2*.3));
      const px2=cx+Math.cos(a2+rot)*rd, py2=cy+Math.sin(a2+rot)*rd*sq;
      if(k===0) dc.moveTo(px2,py2); else dc.lineTo(px2,py2);
    }
    dc.stroke();
  }
}

// ---- hairline scratches: the lens has been cleaned with the wrong cloth ----
for(let m=0;m<nSc;m++){
  const x0=fr(m*8.7+70)*W, y0=fr(m*8.7+71)*Hh;
  const len=u*(.05+.30*fr(m*8.7+72))*sc;
  const ang=fr(m*8.7+73)*TAU, cur=(fr(m*8.7+74)-.5)*1.6;
  const li=lit(x0+Math.cos(ang)*len*.5, y0+Math.sin(ang)*len*.5, 1.1);
  // a scratch is a groove: it is dark until something rakes it, then it flares
  const aa=cl((.16+.62*fr(m*8.7+75))*soil*glare*al*(.04+2.3*li),0,.66);
  if(aa<.002) continue;
  if(survey){
    // non-representational: an optical QC plot — every defect ringed, nothing rendered.
    // Each finding carries its own phase so the plot is never frozen.
    const ph2=.34+.66*(.5+.5*Math.sin(TD*.19+m*1.9))*(.5+.5*Math.sin(TD*.41+m*.7));
    dc.strokeStyle='rgba(150,235,255,'+cl((aa*1.1+.10*soil*al)*1.7*ph2,0,.85).toFixed(4)+')';
    dc.lineWidth=Math.max(1.1,u*.0032*(.7+.6*ph2));
    const rr=len*.5+u*.012;
    dc.beginPath(); dc.arc(x0,y0,rr,0,TAU); dc.stroke();
    dc.beginPath(); dc.moveTo(x0-rr*1.35,y0); dc.lineTo(x0-rr*1.05,y0);
    dc.moveTo(x0+rr*1.05,y0); dc.lineTo(x0+rr*1.35,y0);
    dc.moveTo(x0,y0-rr*1.35); dc.lineTo(x0,y0-rr*1.05);
    dc.moveTo(x0,y0+rr*1.05); dc.lineTo(x0,y0+rr*1.35); dc.stroke();
    continue;
  }
  dc.strokeStyle='rgba(238,242,252,'+aa.toFixed(4)+')';
  dc.lineWidth=Math.max(.6,u*.0013*sc);
  dc.beginPath();
  for(let k=0;k<=7;k++){ const t2=k/7;
    const a2=ang+cur*t2*t2;
    const px2=x0+Math.cos(a2)*len*t2, py2=y0+Math.sin(a2)*len*t2;
    if(k===0) dc.moveTo(px2,py2); else dc.lineTo(px2,py2);
  }
  dc.stroke();
}

// ---- flecks: dust and lint sitting on the glass, each one a tiny out-of-focus blob ----
for(let m=0;m<nFl;m++){
  const fx2=md(fr(m*3.7+100)+.004*Math.sin(TD*.09+m*1.3),1)*W;
  const fy2=md(fr(m*3.7+101)+.004*Math.cos(TD*.07+m*.9),1)*Hh;
  const sz=u*(.0018+.0060*fr(m*3.7+102))*sc;
  const li=lit(fx2,fy2,.85);
  const aa=cl((.30+.95*fr(m*3.7+103))*soil*glare*al*(.05+2.5*li),0,.78);
  if(aa<.003) continue;
  dc.fillStyle=survey?'rgba(150,235,255,'+aa.toFixed(4)+')':'rgba(240,244,252,'+aa.toFixed(4)+')';
  dc.beginPath(); dc.arc(fx2,fy2,sz*(1+li*.6),0,TAU); dc.fill();
}

// ---- a faint coating tint, so the grime is not pure white ----
if(!survey && soil>.25){
  const hr=gR*.9;
  const rg2=dc.createRadialGradient(gx,gy,0,gx,gy,hr);
  const ta=cl(.10*soil*glare*al*fogK,0,.20);
  const cr=Math.round(120+90*Math.cos(H*Math.PI/180)), cg2=Math.round(150+60*Math.sin(H*Math.PI/180)), cb2=210;
  rg2.addColorStop(0,'rgba('+cr+','+cg2+','+cb2+','+ta.toFixed(4)+')');
  rg2.addColorStop(1,'rgba('+cr+','+cg2+','+cb2+',0)');
  dc.fillStyle=rg2; dc.fillRect(gx-hr,gy-hr,hr*2,hr*2);
}

dc.globalCompositeOperation=oldOp;
}
blendMode(BLEND); drawingContext.globalAlpha=1; drawingContext.shadowBlur=0; noStroke(); noTint();
